import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"ADR-009: System ffmpeg instead of a bundled binary","description":"","frontmatter":{},"headers":[],"relativePath":"adr/009-system-ffmpeg.md","filePath":"adr/009-system-ffmpeg.md"}'),o={name:"adr/009-system-ffmpeg.md"};function d(i,e,r,c,l,f){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-009-system-ffmpeg-instead-of-a-bundled-binary" tabindex="-1">ADR-009: System ffmpeg instead of a bundled binary <a class="header-anchor" href="#adr-009-system-ffmpeg-instead-of-a-bundled-binary" aria-label="Permalink to &quot;ADR-009: System ffmpeg instead of a bundled binary&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>ReelForge calls the system <code>ffmpeg</code>/<code>ffprobe</code> (≥ 6.0, overridable with <code>REELFORGE_FFMPEG</code> / <code>REELFORGE_FFPROBE</code>). <code>reelforge doctor</code> checks the version, encoders (libx264, aac, mjpeg) and filters (loudnorm, sidechaincompress, alimiter) and prints per-OS install steps.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>libx264 is GPL: bundling it would change the distribution license and add ~80 MB per platform. Users install ffmpeg once with their package manager.</p>',6)])])}const u=a(o,[["render",d]]);export{p as __pageData,u as default};
